      target.innerHTML=`<h3>${t('候选调查','Candidate investigation')} · ${esc(c.title)}</h3><p>${esc(c.hypothesis)}</p><p>${esc(c.target)} · ${esc(c.status)} · ${esc(data.verification_level)}</p><h4>${t('来源证据与反证','Evidence and counter-evidence')}</h4>`+table(data.evidence,[['id','证据','Evidence'],['polarity','支持 / 反证','Polarity'],['summary','摘要','Summary'],['observation_summary','观察','Observation']],(e,i)=>e.artifact_id?btn('artifact-'+i,'产物关联','Artifact relationships'):'')+`<div data-w-investigation-artifact></div><h4>${t('复验记录','Verification records')}</h4>`+table(data.attempts,[['id','ID','ID'],['oracle','复验器','Oracle'],['status','状态','Status']])+`<h4>${t('复验作业','Verification jobs')}</h4>`+table(data.verification_jobs,[['id','ID','ID'],['status','状态','Status'],['phase','阶段','Phase']])+`<h4>${t('下一步','Next steps')}</h4><ul>${(data.next_steps||[]).map(step=>`<li>${esc(step)}</li>`).join('')}</ul><p>${t('分诊保留历史，不执行复验或生成正式漏洞。','Triage preserves history; it does not run verification or create a verified finding.')}</p>`;
      if(!['verified','archived'].includes(c.status))target.insertAdjacentHTML('beforeend',`<form data-w-triage class="workspace-toolbar">${select('disposition','分诊判断','Disposition',[['needs_evidence','缺少证据','Needs evidence'],['security_hypothesis','安全假设','Security hypothesis'],['not_security','普通观察','Not a security issue'],['duplicate','重复项','Duplicate']].map(([v,zh,en])=>option(v,t(zh,en))).join(''))}${select('duplicate_of','重复于（仅重复项需要）','Duplicate of (duplicates only)',option('',t('请选择','Select'))+(data.peer_candidates||[]).map(peer=>option(peer.id,peer.title||peer.id)).join(''))}<label>${t('判断依据','Reason')}<textarea name="reason" required minlength="3" maxlength="2000"></textarea></label><button type="submit">${t('保存分诊','Save triage')}</button></form>`);
      target.querySelectorAll('[data-w-action^="artifact-"]').forEach(button=>button.onclick=()=>action(host,button,async()=>{const evidence=data.evidence[Number(button.dataset.wAction.split('-')[1])];const detail=await request('/api/v1/workspace/artifacts/'+encodeURIComponent(evidence.artifact_id)+'/relations');if(isCurrent())$('[data-w-investigation-artifact]',target).innerHTML=artifactRelations(detail)}));
