          const [registryResult,admissionResult]=await Promise.allSettled([request('/api/v1/runners'),request('/api/v1/workers/research/admission')]);if(token!==generations[id])return;if(registryResult.status!=='fulfilled')throw registryResult.reason;const data=registryResult.value,admission=admissionResult.status==='fulfilled'?admissionResult.value:null;
